if ($Deep) {
    $scriptContent = [regex]::Replace($scriptContent, '(?<![\w\.])(\d+)(?![\w\.])', {
        param($match)
        $num = [int]$match.Groups[1].Value
        if ($num -le 1) { 
            return $num.ToString() 
        }
        $r = Get-Random -Minimum 1 -Maximum $num
        $a = $r
        $b = $num - $r
        return

